      'id?: string;',
      'asRef?: string[];',
      "attitudeList?: { classificationMarking: string; dataMode: 'REAL' | 'TEST' | 'SIMULATED' | 'EXERCISE'; source: string; ts: string; id?: string; asId?: string; coningAngle?: number; createdAt?: string; createdBy?: string; declination?: number; idOnOrbit?: string; motionType?: string; origin?: string; origNetwork?: string; origObjectId?: string; precPeriod?: number; q1?: number; q1Dot?: number; q2?: number; q2Dot?: number; q3?: number; q3Dot?: number; qc?: number; qcDot?: number; ra?: number; satNo?: number; spinPeriod?: number; xAngle?: number[]; xRate?: number[]; yAngle?: number[]; yRate?: number[]; zAngle?: number[]; zRate?: number[]; }[];",
      'esId?: string;',
