      'id?: string;',
      'centerlineAzimuth?: number;',
      'centerlineElevation?: number;',
      'defaultCHA?: number;',
      'enableDSS?: boolean;',
      'fixedPoints?: { latitude: number; longitude: number; height?: number; }[];',
      'geopotentialModel?: string;',
      "laserDeconflictTargets?: { classificationMarking: string; dataMode: 'REAL' | 'TEST' | 'SIMULATED' | 'EXERCISE'; source: string; id?: string; azimuth?: number; azimuthEnd?: number; azimuthIncrement?: number; azimuthStart?: number; centerlineAzimuth?: number; centerlineElevation?: number; createdAt?: string; createdBy?: string; declination?: number; elevation?: number; elevationEnd?: number; elevationIncrement?: number; elevationStart?: number; fixedPoints?: { latitude: number; longitude: number; height?: number; }[]; idLaserDeconflictRequest?: string; lengthCenterline?: number; lengthLeftRight?: number; lengthUpDown?: number; maximumHeight?: number; minimumHeight?: number; origin?: string; origNetwork?: string; ra?: number; solarSystemBody?: string; sourceDL?: string; starNumber?: number; startDate?: string; targetNumber?: number; targetObjectId?: string; targetObjectNo?: number; }[];",
