      'origObjectId?: string;',
      'platformLocationName?: string;',
      'platformLocationType?: string;',
      'programId?: string;',
      'propagator?: string;',
      'protectList?: number[];',
      'satNo?: number;',
      'sourceEnabled?: boolean;',
      'status?: string;',
      'tags?: string[];',
