ring; source: string; id?: string; alternateFacilityName?: string; altName?: string; amplifier?: { deviceIdentifier?: string; manufacturer?: string; modelName?: string; power?: number; }; antennas?: { antennaDiameter?: number; antennaSize?: number[]; azElFixed?: boolean; feeds?: { freqMax?: number; freqMin?: number; name?: string; polarization?: string; }[]; fixedAzimuth?: number; fixedElevation?: number; maxAzimuths?: number[]; maxElevation?: number; minAzimuths?: number[]; minElevation?: number; name?: string; receiverChannels?: { bandwidth?: number; channelNum?: string; deviceIdentifier?: string; freqMax?: number; freqMin?: number; maxBandwidth?: number; minBandwidth?: number; sensitivity?: number; }[]; transmitChannels?: { power: number; bandwidth?: number; channelNum?: string; deviceIdentifier?: string; freq?: number; freqMax?: number; freqMin?: number; hardwareSampleRate?: number; maxBandwidth?: number; maxGain?: number; minBandwidth?: number; minGain?: number; sampleRates?: number[]; }[]; }[]; barrageNoiseBandwidth?: number; bitRunTime?: number; createdAt?: string; createdBy?: string; description?: string; designator?: string; dopplerNoise?: number; drfmInstantaneousBandwidth?: number; family?: string; fixedAttenuation?: number; idManufacturerOrg?: string; idProductionFacilityLocation?: string; loanedToCocom?: string; notes?: string; numBits?: number; numChannels?: number; origin?: string; origNetwork?: string; powerOffsets?: { frequencyBand?: string; powerOffset?: number; }[]; prepTime?: number; primaryCocom?: string; productionFacilityName?: string; receiverType?: string; secondaryNotes?: string; services?: { name?: string; version?: string; }[]; systemSensitivityEnd?: number; systemSensitivityStart?: number; ttps?: { outputSignalName?: string; techniqueDefinitions?: { name?: string; paramDefinitions?: { defaultValue?: string; max?: number; min?: number; name?: string; optional?: boolean; type?: string; units?: string; validValues?: string[]; }[]; }[]; }[];