      'sendNotification?: boolean;',
      'id?: string;',
      'attachment?: { author?: string; content_length?: number; content_type?: string; date?: string; keywords?: string; language?: string; title?: string; };',
      'classificationMarking?: string;',
      'createdAt?: string;',
      'createdBy?: string;',
      'deleteOn?: number;',
      'description?: string;',
