      "entity?: { classificationMarking: string; dataMode: 'REAL' | 'TEST' | 'SIMULATED' | 'EXERCISE'; name: string; source: string; type: string; countryCode?: string; createdAt?: string; createdBy?: string; idEntity?: string; idLocation?: string; idOnOrbit?: string; idOperatingUnit?: string; location?: { classificationMarking: string; dataMode: 'REAL' | 'TEST' | 'SIMULATED' | 'EXERCISE'; name: string; source: string; altitude?: number; countryCode?: string; createdAt?: string; createdBy?: string; idLocation?: string; lat?: number; lon?: number; origin?: string; origNetwork?: string; }; onOrbit?: { classificationMarking: string; dataMode: 'REAL' | 'TEST' | 'SIMULATED' | 'EXERCISE'; satNo: number; source: string; altName?: string; category?: string; commonName?: string; constellation?: string; countryCode?: string; createdAt?: string; createdBy?: string; decayDate?: string; idOnOrbit?: string; intlDes?: string; launchDate?: string; launchSiteId?: string; lifetimeYears?: number; missionNumber?: string; objectType?: 'ROCKET BODY' | 'DEBRIS' | 'PAYLOAD' | 'PLATFORM' | 'MANNED' | 'UNKNOWN'; origin?: string; origNetwork?: string; }; origin?: string; origNetwork?: string; ownerType?: 'Commercial' | 'Government' | 'Academic' | 'Consortium' | 'Other'; taskable?: boolean; urls?: string[]; };",
      'eval?: number;',
